public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of the n-SECTIONS already visited
    boolean[][] visited = new boolean[n][n];
    // Initialize the queue for BFS traversal
    Queue<int[]> queue = new ArrayDeque<>();
    // Push the starting n-SECTION to the queue
    queue.add(start);
    // Perform BFS traversal
    while (!queue.isEmpty()) {
        // Dequeue the first n-SECTION from the queue
        int[] current = queue.poll();
        // If the n-SECTION is not visited, mark it as visited
        if (!visited[current[0]][current[1]]) {
            visited[current[0]][current[1]] = true;
            // If the current n-SECTION is the end n-SECTION, return "can be travelled"
            if (current[0] == end[0] && current[1] == end[1]) {
                return "can be travelled";
            }
            // Push the neighbors of the current n-SECTION that have not been visited yet
            for (int[] neighbor : paths[current[0]][current[1]]) {
                if (!visited[neighbor[0]][neighbor[1]]) {
                    queue.add(neighbor);
                }
            }
        }
    }
    // If the n-SECTION is not found during BFS traversal, return "cannot be travelled"
    return "cannot be travelled";
}

