public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time to 0
    int minTime = 0;
    // Initialize the starting node as 0
    int startNode = 0;
    // Create a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];
    // Create a queue for BFS traversal
    Queue<Integer> queue = new LinkedList<>();
    // Add the starting node to the queue
    queue.add(startNode);
    // Mark the starting node as visited
    visited[startNode] = true;
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int currentNode = queue.remove();
        // If the current node has an apple, add the time to collect it to the minimum time
        if (hasApple[currentNode]) {
            minTime += 2;
        }
        // Loop through all the neighbors of the current node
        for (int neighbor : edges[currentNode]) {
            // If the neighbor has not been visited, mark it as visited and add it to the queue
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }
    // Return the minimum time to collect all apples and return to the starting node
    return minTime;
}

