public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] dp = new int[n];
    dp[0] = 1;
    for (int i = 1; i < n; i++) {
        dp[i] = dp[i - 1];
        for (int j = 0; j < i; j++) {
            if (s.substring(j, i + 1).equals(s.substring(i - j, i + 1)) && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
            }
        }
    }
    return dp[n - 1];
}

