    Set<Integer> uniqueElements = new HashSet<>();
    // Iterate over the input array
    for (int num : nums) {
        // If the current element is not already in the set, add it and its sum to the result
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
        }
