    for (int i = 1; i * i <= n; i++) {
        // If i is a perfect square, add it to the list
        if (i * i == n) {
            perfectSquares.add(i);
        }
    }

    // Return the minimum number of perfect squares needed to sum up to n
    return perfectSquares.size();
}

